import Complex64Array = require( '@stdlib/array/complex64' );
import Complex64 = require( '@stdlib/complex/float32/ctor' );
import ctrsm = require( './index' );


// TESTS //

// The function returns a Complex64Array...
{
	const A = new Complex64Array( 4 );
	const B = new Complex64Array( 2 );
	const alpha = new Complex64( 1.0, 0.0 );

	ctrsm( 'row-major', 'left', 'upper', 'no-transpose', 'non-unit', 2, 1, alpha, A, 2, B, 1 ); // $ExpectType Complex64Array
}

// The compiler throws an error if the function is provided a first argument which is not a string...
{
	const A = new Complex64Array( 4 );
	const B = new Complex64Array( 2 );
	const alpha = new Complex64( 1.0, 0.0 );

	ctrsm( 10, 'left', 'upper', 'no-transpose', 'non-unit', 2, 1, alpha, A, 2, B, 1 ); // $ExpectError
	ctrsm( true, 'left', 'upper', 'no-transpose', 'non-unit', 2, 1, alpha, A, 2, B, 1 ); // $ExpectError
	ctrsm( false, 'left', 'upper', 'no-transpose', 'non-unit', 2, 1, alpha, A, 2, B, 1 ); // $ExpectError
	ctrsm( null, 'left', 'upper', 'no-transpose', 'non-unit', 2, 1, alpha, A, 2, B, 1 ); // $ExpectError
	ctrsm( undefined, 'left', 'upper', 'no-transpose', 'non-unit', 2, 1, alpha, A, 2, B, 1 ); // $ExpectError
	ctrsm( [], 'left', 'upper', 'no-transpose', 'non-unit', 2, 1, alpha, A, 2, B, 1 ); // $ExpectError
	ctrsm( {}, 'left', 'upper', 'no-transpose', 'non-unit', 2, 1, alpha, A, 2, B, 1 ); // $ExpectError
	ctrsm( ( x: number ): number => x, 'left', 'upper', 'no-transpose', 'non-unit', 2, 1, alpha, A, 2, B, 1 ); // $ExpectError
}

// The compiler throws an error if the function is provided a sixth argument which is not a number...
{
	const A = new Complex64Array( 4 );
	const B = new Complex64Array( 2 );
	const alpha = new Complex64( 1.0, 0.0 );

	ctrsm( 'row-major', 'left', 'upper', 'no-transpose', 'non-unit', '2', 1, alpha, A, 2, B, 1 ); // $ExpectError
	ctrsm( 'row-major', 'left', 'upper', 'no-transpose', 'non-unit', true, 1, alpha, A, 2, B, 1 ); // $ExpectError
	ctrsm( 'row-major', 'left', 'upper', 'no-transpose', 'non-unit', false, 1, alpha, A, 2, B, 1 ); // $ExpectError
	ctrsm( 'row-major', 'left', 'upper', 'no-transpose', 'non-unit', null, 1, alpha, A, 2, B, 1 ); // $ExpectError
	ctrsm( 'row-major', 'left', 'upper', 'no-transpose', 'non-unit', undefined, 1, alpha, A, 2, B, 1 ); // $ExpectError
	ctrsm( 'row-major', 'left', 'upper', 'no-transpose', 'non-unit', [], 1, alpha, A, 2, B, 1 ); // $ExpectError
	ctrsm( 'row-major', 'left', 'upper', 'no-transpose', 'non-unit', {}, 1, alpha, A, 2, B, 1 ); // $ExpectError
	ctrsm( 'row-major', 'left', 'upper', 'no-transpose', 'non-unit', ( x: number ): number => x, 1, alpha, A, 2, B, 1 ); // $ExpectError
}

// The compiler throws an error if the function is provided an eighth argument which is not a complex number...
{
	const A = new Complex64Array( 4 );
	const B = new Complex64Array( 2 );

	ctrsm( 'row-major', 'left', 'upper', 'no-transpose', 'non-unit', 2, 1, 1.0, A, 2, B, 1 ); // $ExpectError
	ctrsm( 'row-major', 'left', 'upper', 'no-transpose', 'non-unit', 2, 1, '1.0', A, 2, B, 1 ); // $ExpectError
	ctrsm( 'row-major', 'left', 'upper', 'no-transpose', 'non-unit', 2, 1, true, A, 2, B, 1 ); // $ExpectError
	ctrsm( 'row-major', 'left', 'upper', 'no-transpose', 'non-unit', 2, 1, false, A, 2, B, 1 ); // $ExpectError
	ctrsm( 'row-major', 'left', 'upper', 'no-transpose', 'non-unit', 2, 1, null, A, 2, B, 1 ); // $ExpectError
	ctrsm( 'row-major', 'left', 'upper', 'no-transpose', 'non-unit', 2, 1, undefined, A, 2, B, 1 ); // $ExpectError
	ctrsm( 'row-major', 'left', 'upper', 'no-transpose', 'non-unit', 2, 1, [], A, 2, B, 1 ); // $ExpectError
	ctrsm( 'row-major', 'left', 'upper', 'no-transpose', 'non-unit', 2, 1, {}, A, 2, B, 1 ); // $ExpectError
	ctrsm( 'row-major', 'left', 'upper', 'no-transpose', 'non-unit', 2, 1, ( x: number ): number => x, A, 2, B, 1 ); // $ExpectError
}

// The compiler throws an error if the function is provided a ninth argument which is not a Complex64Array...
{
	const B = new Complex64Array( 2 );
	const alpha = new Complex64( 1.0, 0.0 );

	ctrsm( 'row-major', 'left', 'upper', 'no-transpose', 'non-unit', 2, 1, alpha, 10, 2, B, 1 ); // $ExpectError
	ctrsm( 'row-major', 'left', 'upper', 'no-transpose', 'non-unit', 2, 1, alpha, '10', 2, B, 1 ); // $ExpectError
	ctrsm( 'row-major', 'left', 'upper', 'no-transpose', 'non-unit', 2, 1, alpha, true, 2, B, 1 ); // $ExpectError
	ctrsm( 'row-major', 'left', 'upper', 'no-transpose', 'non-unit', 2, 1, alpha, false, 2, B, 1 ); // $ExpectError
	ctrsm( 'row-major', 'left', 'upper', 'no-transpose', 'non-unit', 2, 1, alpha, null, 2, B, 1 ); // $ExpectError
	ctrsm( 'row-major', 'left', 'upper', 'no-transpose', 'non-unit', 2, 1, alpha, undefined, 2, B, 1 ); // $ExpectError
	ctrsm( 'row-major', 'left', 'upper', 'no-transpose', 'non-unit', 2, 1, alpha, [ '1' ], 2, B, 1 ); // $ExpectError
	ctrsm( 'row-major', 'left', 'upper', 'no-transpose', 'non-unit', 2, 1, alpha, {}, 2, B, 1 ); // $ExpectError
	ctrsm( 'row-major', 'left', 'upper', 'no-transpose', 'non-unit', 2, 1, alpha, ( x: number ): number => x, 2, B, 1 ); // $ExpectError
}

// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	const A = new Complex64Array( 4 );
	const B = new Complex64Array( 2 );
	const alpha = new Complex64( 1.0, 0.0 );

	ctrsm(); // $ExpectError
	ctrsm( 'row-major' ); // $ExpectError
	ctrsm( 'row-major', 'left', 'upper', 'no-transpose', 'non-unit', 2, 1, alpha, A, 2, B ); // $ExpectError
	ctrsm( 'row-major', 'left', 'upper', 'no-transpose', 'non-unit', 2, 1, alpha, A, 2, B, 1, 0 ); // $ExpectError
}

// Attached to main export is an `ndarray` method which returns a Complex64Array...
{
	const A = new Complex64Array( 4 );
	const B = new Complex64Array( 2 );

	ctrsm.ndarray( 'row-major', 'left', 'upper', 'no-transpose', 'non-unit', 2, 1, 1.0, 0.0, A, 2, 0, B, 1, 0 ); // $ExpectType Complex64Array
}

// The compiler throws an error if the `ndarray` method is provided an unsupported number of arguments...
{
	const A = new Complex64Array( 4 );
	const B = new Complex64Array( 2 );

	ctrsm.ndarray(); // $ExpectError
	ctrsm.ndarray( 'row-major' ); // $ExpectError
	ctrsm.ndarray( 'row-major', 'left', 'upper', 'no-transpose', 'non-unit', 2, 1, 1.0, 0.0, A, 2, 0, B, 1 ); // $ExpectError
	ctrsm.ndarray( 'row-major', 'left', 'upper', 'no-transpose', 'non-unit', 2, 1, 1.0, 0.0, A, 2, 0, B, 1, 0, 0 ); // $ExpectError
}
